   388→        protected virtual TransactionResult ValidateGas(Transaction tx, BlockHeader header, long minGasRequired, bool validate)
   389→        {
   390→            if (tx.GasLimit < minGasRequired)
   391→            {
   392→                TraceLogInvalidTx(tx, $"GAS_LIMIT_BELOW_INTRINSIC_GAS {tx.GasLimit} < {minGasRequired}");
   393→                return TransactionResult.GasLimitBelowIntrinsicGas;
   394→            }
   395→
   396→            if (validate && tx.GasLimit > header.GasLimit - header.GasUsed)
   397→            {
   398→                TraceLogInvalidTx(tx, $"BLOCK_GAS_LIMIT_EXCEEDED {tx.GasLimit} > {header.GasLimit} - {header.GasUsed}");
   399→                return TransactionResult.BlockGasLimitExceeded;
   400→            }
   401→
   402→            return TransactionResult.Ok;
   403→        }
