   406→        protected virtual bool RecoverSenderIfNeeded(Transaction tx, IReleaseSpec spec, ExecutionOptions opts, in UInt256 effectiveGasPrice)
   407→        {
   408→            bool deleteCallerAccount = false;
   409→            Address? sender = tx.SenderAddress;
   410→            if (sender is null || !WorldState.AccountExists(sender))
